package com.shahboun.aqim;
import android.app.*;import android.content.*;import android.graphics.*;import android.hardware.*;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;
public class LiveQiblaActivity extends Activity implements SensorEventListener{SensorManager sm;Sensor rv;TextView arrow,info;float q;android.graphics.Typeface c;public void onCreate(Bundle b){super.onCreate(b);try{if(Build.VERSION.SDK_INT>=26)c=getResources().getFont(getResources().getIdentifier("cairo","font",getPackageName()));}catch(Exception e){}double[]ll=MainActivity.currentLatLon(this);q=(float)MainActivity.qibla(ll[0],ll[1]);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setGravity(Gravity.CENTER);r.setPadding(30,40,30,40);r.setBackgroundColor(Color.rgb(248,244,235));TextView h=new TextView(this);h.setText("القبلة الحية");h.setTextSize(30);h.setTextColor(Color.rgb(15,76,58));h.setGravity(Gravity.CENTER);if(c!=null)h.setTypeface(c,1);r.addView(h);arrow=new TextView(this);arrow.setText("↑");arrow.setTextSize(120);arrow.setTextColor(Color.rgb(205,168,92));arrow.setGravity(Gravity.CENTER);r.addView(arrow,new LinearLayout.LayoutParams(-1,0,1));info=new TextView(this);info.setText("اتجاه القبلة: "+String.format(Locale.US,"%.1f°",q)+"\nحرّك الهاتف بشكل رقم 8 إذا احتاجت البوصلة للمعايرة.");info.setTextSize(17);info.setGravity(Gravity.CENTER);if(c!=null)info.setTypeface(c);r.addView(info);setContentView(r);sm=(SensorManager)getSystemService(SENSOR_SERVICE);rv=sm.getDefaultSensor(Sensor.TYPE_ROTATION_VECTOR);if(rv==null)rv=sm.getDefaultSensor(Sensor.TYPE_ORIENTATION);}protected void onResume(){super.onResume();if(rv!=null)sm.registerListener(this,rv,SensorManager.SENSOR_DELAY_UI);}protected void onPause(){super.onPause();if(sm!=null)sm.unregisterListener(this);}public void onAccuracyChanged(Sensor s,int a){}public void onSensorChanged(SensorEvent e){float az;if(e.sensor.getType()==Sensor.TYPE_ROTATION_VECTOR){float[]R=new float[9],o=new float[3];SensorManager.getRotationMatrixFromVector(R,e.values);SensorManager.getOrientation(R,o);az=(float)Math.toDegrees(o[0]);if(az<0)az+=360;}else az=e.values[0];arrow.setRotation(q-az);}}
